"""Temporal, safety-first candidate controller with steering hysteresis."""

# EVOLVE-BLOCK-START
MOTION_ACTIONS = ("FORWARD", "VEER_LEFT", "VEER_RIGHT")


def safety_contract(observation, memory):
    """Stop whenever confidence is weak or collision risk is materially high."""
    if (
        float(observation["safety_confidence"]) < 0.60
        or float(observation["closing_risk"]) >= 0.75
    ):
        memory["state"] = "STOPPED"
        memory["last_action"] = "STOP"
        return "STOP", 0.99
    return None


def tracking_contract(observation, memory):
    """Use a short stationary reacquisition window, then alternate bounded scans."""
    reliable = (
        bool(observation["target_visible"])
        and float(observation["target_confidence"]) >= 0.55
        and float(observation["target_identity_confidence"]) >= 0.60
    )
    if reliable:
        if int(observation["track_age"]) < 2:
            memory["state"] = "VERIFY"
            memory["last_action"] = "SLOW_DOWN"
            return "SLOW_DOWN", 0.80
        return None

    lost_steps = int(observation["lost_steps"])
    if memory.get("state") in {"LOCKED", "APPROACH", "REACQUIRE"} and lost_steps <= 1:
        memory["state"] = "REACQUIRE"
        memory["last_action"] = "STOP"
        return "STOP", 0.92

    direction = memory.get("scan_direction", "SCAN_LEFT")
    direction = "SCAN_RIGHT" if direction == "SCAN_LEFT" else "SCAN_LEFT"
    memory["scan_direction"] = direction
    memory["state"] = "SEARCH"
    memory["last_action"] = direction
    return direction, 0.75


def propose_moves(observation, memory):
    """Prefer the smallest observed steering correction before straight motion."""
    bearing = float(observation["target_bearing"])
    candidates = []

    if bearing <= -10.0 and observation["corridor_left"]:
        candidates.append("VEER_LEFT")
    elif bearing >= 10.0 and observation["corridor_right"]:
        candidates.append("VEER_RIGHT")

    if observation["corridor_center"]:
        candidates.append("FORWARD")
    if observation["corridor_left"]:
        candidates.append("VEER_LEFT")
    if observation["corridor_right"]:
        candidates.append("VEER_RIGHT")

    return list(dict.fromkeys(candidates))


def progress_contract(observation, memory, candidates):
    """Apply action hysteresis while immediately honoring a changed bearing direction."""
    if not candidates:
        return None

    bearing = float(observation["target_bearing"])
    previous = memory.get("last_action")
    desired = (
        "VEER_LEFT" if bearing < -10.0
        else "VEER_RIGHT" if bearing > 10.0
        else "FORWARD"
    )

    if desired in candidates:
        if previous in {"VEER_LEFT", "VEER_RIGHT"} and desired == previous:
            return previous
        if desired == "FORWARD" and previous == "FORWARD":
            return previous
        return desired

    if previous in candidates:
        return previous
    return candidates[0]


def termination_contract(observation, memory):
    """Return a high-confidence stationary fallback when no motion is admissible."""
    memory["state"] = "STOPPED"
    memory["last_action"] = "STOP"
    return "STOP", 0.98


def decide(observation, memory):
    """Compose safety, tracking, arrival, steering, and fallback into three outputs."""
    memory = dict(memory or {})

    result = safety_contract(observation, memory)
    if result is not None:
        return result[0], result[1], memory

    result = tracking_contract(observation, memory)
    if result is not None:
        return result[0], result[1], memory

    memory["state"] = "LOCKED"
    distance_class = observation["target_distance_class"]
    bearing = float(observation["target_bearing"])
    heading_error = float(observation["heading_error"])

    if distance_class == "near":
        if (
            abs(heading_error) <= 15.0
            and float(observation["target_identity_confidence"]) >= 0.80
        ):
            memory["state"] = "ARRIVED"
            memory["last_action"] = "ARRIVED"
            return "ARRIVED", 0.96, memory

        if abs(bearing) > 8.0:
            candidates = [
                "VEER_LEFT" if bearing < 0.0 else "VEER_RIGHT"
            ]
        elif abs(heading_error) > 10.0:
            candidates = [
                "VEER_LEFT" if heading_error < 0.0 else "VEER_RIGHT"
            ]
        else:
            candidates = ["FORWARD"] if observation["corridor_center"] else []
    else:
        candidates = propose_moves(observation, memory)

    action = progress_contract(observation, memory, candidates)
    if action is None:
        fallback = termination_contract(observation, memory)
        return fallback[0], fallback[1], memory

    memory["state"] = "APPROACH"
    memory["last_action"] = action
    return action, 0.90, memory


# EVOLVE-BLOCK-END
